<template>
  <div class="flow-page" v-loading="loading"><main><header><div><h1>审核流程模板</h1><p>统一配置业务审核节点、条件、处理角色、时限与通知</p></div><div><el-button size="small" icon="el-icon-circle-check" @click="validateAll">校验全部流程</el-button><el-button size="small" type="success" icon="el-icon-plus" @click="$router.push('/approvals/flows/create')">新增审核流程</el-button></div></header><div class="kpis"><article><span>已启用流程</span><b class="blue">{{ summary.enabled||0 }}</b><i class="el-icon-document blue"/></article><article><span>草稿</span><b>{{ summary.draft||0 }}</b><i class="el-icon-tickets orange"/></article><article><span>配置异常</span><b class="red">{{ summary.invalid||0 }}</b><i class="el-icon-warning-outline red"/></article><article><span>本月触发</span><b>{{ summary.monthly_triggered||0 }}</b><i class="el-icon-top-right green"/></article></div><section class="filters"><label>业务模块<el-select v-model="filters.business_module" clearable size="small" placeholder="请选择业务模块"><el-option label="销售管理" value="销售管理"/><el-option label="采购管理" value="采购管理"/></el-select></label><label>业务场景<el-input v-model.trim="filters.business_type" size="small" placeholder="请输入业务场景"/></label><label>模板状态<el-select v-model="filters.status" clearable size="small" placeholder="请选择模板状态"><el-option label="启用中" value="enabled"/><el-option label="已停用" value="disabled"/><el-option label="草稿" value="draft"/></el-select></label><label>关键字<el-input v-model.trim="filters.keyword" size="small" placeholder="请输入流程名称/编码/描述"/></label><div><el-button size="small" type="success" @click="search">查询</el-button><el-button size="small" @click="reset">重置</el-button></div></section><section class="table"><el-table :data="rows" border size="mini"><el-table-column prop="flow_code" label="流程编码" min-width="155"/><el-table-column prop="flow_name" label="流程名称" min-width="155"/><el-table-column prop="business_module" label="业务模块" width="100"/><el-table-column prop="business_scene" label="业务场景" min-width="130"/><el-table-column label="版本" width="60"><template slo