-warning-outline purple"/>版本冲突 <b>0</b></p></section></aside></div>
</template>
<script>
import { copyApprovalFlow, getApprovalFlow, getApprovalFlowSummary, listApprovalFlows, toggleApprovalFlow, validateApprovalFlow } from '@/api/erp/approval'
const blank=()=>({business_module:'',business_type:'',status:'',keyword:''})
export default{name:'ApprovalFlowList',data:()=>({loading:false,rows:[],summary:{},filters:blank(),page:1,perPage:20,total:0,mechanisms:[{title:'业务接入器',text:'通过 business_type + business_id + snapshot 接入业务数据。'},{title:'条件路由',text:'基于金额、风险、部门、字段变化等条件进行路由分支与合并。'},{title:'节点处理人',text:'支持角色、部门负责人、指定人、表达式动态计算处理人。'},{title:'通知事件',text:'通过 WebSocket + 站内通知实时触达处理进度与结果。'},{title:'回调机制',text:'审批通过/驳回触发回调，支持 approved/rejected hooks。'}]}),created(){this.loadAll()},methods:{async loadAll(){this.loading=true;try{await Promise.all([this.load(),this.loadSummary()])}finally{this.loading=false}},async load(){const{data}=await listApprovalFlows({...this.filters,page:this.page,per_page:this.perPage});this.rows=data.data||[];this.total=Number(data.total||0)},async loadSummary(){const{data}=await getApprovalFlowSummary();this.summary=data.data||{}},search(){this.page=1;this.load()},reset(){this.filters=blank();this.search()},sizeChange(v){this.perPage=v;this.page=1;this.load()},open(row,mode){this.$router.push({path:`/approvals/flows/${row.id}/edit`,query:{mode}})},async copy(row){await this.$confirm(`复制流程“${row.flow_name}”为新草稿？`,'复制流程');await copyApprovalFlow(row.id);this.$message.success('已复制为新草稿');this.loadAll()},async toggle(row){const enabled=row.status!=='enabled';await this.$confirm(`确认${enabled?'启用':'停用'}流程“${row.flow_name}”？`,'状态确认',{type:'warning'});await toggleApprovalFlow(row.id,enabled);this.$message.success(enabled?'流程已启用':'流程已停用');this.loadAll()},async versions(row){const{data}=await getApprovalFlow(row.id);const versions=(data.data&&data.data.versions)||[];this.$alert(versions.map(v=>`v${v.version_no} · ${v.version_status==='published'?'已发布':'草稿'} · ${this.time(v.published_at||v.updated_at)} · ${v.published_by||v.updated_by||'-'}`).join('\n')||'暂无版本','版本记录',{customClass:'approval-version-dialog',confirmButtonText:'关闭'})},async validateAll(){let invalid=0;for(const row of this.rows){const{data}=await getApprovalFlow(row.id);const def=data.data&&data.data.editing_version&&data.data.editing_version.definition_snapshot||{};const result=await validateApprovalFlow(def);if(!result.data.data.valid)invalid++}this.$message[invalid?'warning':'success'](invalid?`发现 ${invalid} 个流程配置异常`:'当前页流程校验全部通过')},time(v){return v?String(v).replace('T',' ').replace(/\.\d+Z$/,'').slice(0,16):'-'}}}
